const express = require('express');
const Order = require('../models/order');
const router = express.Router();

router.post('/orders', async (req, res) => {
  try {
    if (!req.body.customerId) return res.status(400).json({ error: 'customerId required' });
    if (!req.body.items || !req.body.items.length) return res.status(400).json({ error: 'items required' });
    let total = 0;
    for (const item of req.body.items) {
      total += item.price * item.qty;
    }
    if (req.body.promoCode === 'SAVE10') total = total * 0.9;
    const order = await Order.create({ customerId: req.body.customerId, items: req.body.items, total, status: 'pending' });
    res.status(201).json(order);
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Something went wrong' });
  }
});

module.exports = router;
